import { check } from 'k6';
import { signedHeaders } from './aws-signature.k6.js';

// Expected signatures were independently generated by botocore SigV4Auth.
const vectors = JSON.parse(open('./test-data/sigv4.json'));
export const options = { vus: 1, iterations: 1, thresholds: { checks: ['rate==1'] } };
export default function () {
  for (const vector of vectors) {
    const headers = signedHeaders(vector.method, vector.host, vector.path, vector.body,
      vector.service, vector.region, vector.credentials, new Date(vector.now), vector.extra_headers || {});
    check(headers, { [`${vector.service} signature matches botocore`]:
      (value) => value.authorization === vector.expected_authorization });
  }
}
